"use strict";
const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api), ["buildReadingWorkspace"]);
const { buildReadingWorkspace } = api;

for (const [title, entries] of [[undefined, []], ["", []], [" ", []], [" x", []], ["x ", []], [3, []], ["x", null], ["x", {}], ["x", ["a", 2]]]) {
  assert.throws(() => buildReadingWorkspace(title, entries), TypeError);
}

const empty = buildReadingWorkspace("Books", []);
assert.deepStrictEqual(empty, {
  type: "workspace",
  navigation: { type: "navigation", label: "Books" },
  main: { type: "content", message: "Ready to review.", entries: [] }
});

const entries = ["first", "", "first"];
const one = buildReadingWorkspace("Review", entries);
entries.push("late");
assert.deepStrictEqual(one.main.entries, ["first", "", "first"]);
assert.notStrictEqual(one.main.entries, entries);
const two = buildReadingWorkspace("Review", ["first", "", "first"]);
assert.notStrictEqual(one, two);
assert.notStrictEqual(one.navigation, two.navigation);
assert.notStrictEqual(one.main, two.main);
assert.notStrictEqual(one.main.entries, two.main.entries);

